// Shape the website support form into a Zammad ticket for the Support group.
const item = $input.first();
const f = item.json.body || {};
const clean = (v) => String(v ?? '').trim();
const PRIORITY = { Critical: '3 high', High: '3 high', Normal: '2 normal', Low: '1 low' };
const priority = clean(f.priority);
const details = [
  ['Name', f.name],
  ['Company', f.company],
  ['Email', f.email],
  ['Phone', f.phone],
  ['Preferred contact', f.preferred_contact_method],
  ['Best time to contact', f.best_contact_time],
  ['Category', f.category],
  ['Priority', priority],
  ['Who is affected', f.users_affected],
  ['Issue began', f.issue_started],
  ['Remote support allowed', clean(f.remote_support_permission) === 'yes' ? 'Yes' : 'No'],
  ['Submitted', f.submitted_at],
]
  .map(([label, value]) => [label, clean(value)])
  .filter(([, value]) => value !== '')
  .map(([label, value]) => `${label}: ${value}`);
const sections = [details.join('\n'), `Description:\n${clean(f.description)}`];
if (clean(f.troubleshooting_attempted)) sections.push(`Already tried:\n${clean(f.troubleshooting_attempted)}`);

// Files arrive as binary properties attachment_1 ... attachment_5; Zammad wants base64.
const attachments = [];
const keys = Object.keys(item.binary || {}).filter((key) => key.startsWith('attachment_')).sort();
for (const key of keys) {
  const meta = item.binary[key];
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  attachments.push({
    filename: meta.fileName || key,
    data: buffer.toString('base64'),
    'mime-type': meta.mimeType || 'application/octet-stream',
  });
}

const ticket = {
  title: clean(f.subject),
  group: 'Support',
  customer_id: `guess:${clean(f.email)}`,
  priority: PRIORITY[priority] || '2 normal',
  article: {
    subject: clean(f.subject),
    body: sections.join('\n\n'),
    type: 'web',
    sender: 'Customer',
    internal: false,
    content_type: 'text/plain',
    attachments,
  },
};
if (priority === 'Critical') ticket.tags = 'critical';
return [{ json: { ticket } }];
